/**
 * High-level RustO OCR Engine for multi-platform bindings.
 */
open class RustO: Disposable, AutoCloseable, RustOInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_rusto_fn_free_rusto(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_rusto_fn_clone_rusto(handle, status)
        }
    }

    
    /**
     * Runs text detection and recognition on an image source.
     */
    @Throws(RustoBindingException::class)override fun `detectText`(`source`: ImageSource, `options`: OcrRunOptions): DetectTextResult {
            return FfiConverterTypeDetectTextResult.lift(
    callWithHandle {
    uniffiRustCallWithError(RustoBindingException) { _status ->
    UniffiLib.uniffi_rusto_fn_method_rusto_detect_text(
        it,
        FfiConverterTypeImageSource.lower(`source`),FfiConverterTypeOcrRunOptions.lower(`options`),_status)
}
    }
    )
    }
    

    
    /**
     * Runs text detection and recognition on raw decoded interleaved 24-bit RGB pixel bytes.
     */
    @Throws(RustoBindingException::class)override fun `detectTextRgb`(`pixels`: kotlin.ByteArray, `width`: kotlin.UInt, `height`: kotlin.UInt, `stride`: kotlin.ULong, `options`: OcrRunOptions): DetectTextResult {
            return FfiConverterTypeDetectTextResult.lift(
    callWithHandle {
    uniffiRustCallWithError(RustoBindingException) { _status ->
    UniffiLib.uniffi_rusto_fn_method_rusto_detect_text_rgb(
        it,
        FfiConverterByteArray.lower(`pixels`),FfiConverterUInt.lower(`width`),FfiConverterUInt.lower(`height`),FfiConverterULong.lower(`stride`),FfiConverterTypeOcrRunOptions.lower(`options`),_status)
}
    }
    )
    }
    

    
    /**
     * Returns the engine library version string.
     */override fun `version`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_rusto_fn_method_rusto_version(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    companion object {
        
    /**
     * Initializes an OCR engine instance with structured InitializeConfig.
     */
    @Throws(RustoBindingException::class) fun `initialize`(`config`: InitializeConfig): RustO {
            return FfiConverterTypeRustO.lift(
    uniffiRustCallWithError(RustoBindingException) { _status ->
    UniffiLib.uniffi_rusto_fn_constructor_rusto_initialize(
    
        FfiConverterTypeInitializeConfig.lower(`config`),_status)
}
    )
    }
    

        
    /**
     * Initializes an OCR engine instance from a JSON configuration string.
     */
    @Throws(RustoBindingException::class) fun `initializeFromJson`(`configJson`: kotlin.String): RustO {
            return FfiConverterTypeRustO.lift(
    uniffiRustCallWithError(RustoBindingException) { _status ->
    UniffiLib.uniffi_rusto_fn_constructor_rusto_initialize_from_json(
    
        FfiConverterString.lower(`configJson`),_status)
}
    )
    }
    

        
    }
    
}


/**
 * @suppress
 */
public object FfiConverterTypeRustO: FfiConverter<RustO, Long> {
    override fun lower(value: RustO): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): RustO {
        return RustO(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): RustO {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: RustO) = 8UL

    override fun write(value: RustO, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



