    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDetectTextResult : FfiConverterRustBuffer<DetectTextResult>{
    override fun read(buf: ByteBuffer): DetectTextResult {
        return when(buf.getInt()) {
            1 -> DetectTextResult.Structured(
                FfiConverterSequenceTypeTextResult.read(buf),
                )
            2 -> DetectTextResult.Spatial(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DetectTextResult) = when(value) {
        is DetectTextResult.Structured -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeTextResult.allocationSize(value.`results`)
            )
        }
        is DetectTextResult.Spatial -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
    }

    override fun write(value: DetectTextResult, buf: ByteBuffer) {
        when(value) {
            is DetectTextResult.Structured -> {
                buf.putInt(1)
                FfiConverterSequenceTypeTextResult.write(value.`results`, buf)
                Unit
            }
            is DetectTextResult.Spatial -> {
                buf.putInt(2)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





