/**
 * Output format granularity for text detection.
 */

enum class OutputGranularity {
    
    /**
     * Group recognized tokens into lines (default).
     */
    LINES,
    /**
     * Return individual word-level tokens.
     */
    WORDS,
    /**
     * Reconstruct a 2D spatial text layout preserving visual arrangement.
     */
    SPATIAL;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeOutputGranularity: FfiConverterRustBuffer<OutputGranularity> {
    override fun read(buf: ByteBuffer) = try {
        OutputGranularity.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: OutputGranularity) = 4UL

    override fun write(value: OutputGranularity, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class RustoBindingException: kotlin.Exception() {
    
    class Initialization(
        
        val `msg`: kotlin.String
        ) : RustoBindingException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Preprocess(
        
        val `msg`: kotlin.String
        ) : RustoBindingException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Inference(
        
        val `msg`: kotlin.String
        ) : RustoBindingException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Postprocess(
        
        val `msg`: kotlin.String
        ) : RustoBindingException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidInput(
        
        val `msg`: kotlin.String
        ) : RustoBindingException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RustoBindingException> {
        override fun lift(error_buf: RustBuffer.ByValue): RustoBindingException = FfiConverterTypeRustoBindingError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRustoBindingError : FfiConverterRustBuffer<RustoBindingException> {
    override fun read(buf: ByteBuffer): RustoBindingException {
        

        return when(buf.getInt()) {
            1 -> RustoBindingException.Initialization(
                FfiConverterString.read(buf),
                )
            2 -> RustoBindingException.Preprocess(
                FfiConverterString.read(buf),
                )
            3 -> RustoBindingException.Inference(
                FfiConverterString.read(buf),
                )
            4 -> RustoBindingException.Postprocess(
                FfiConverterString.read(buf),
                )
            5 -> RustoBindingException.InvalidInput(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RustoBindingException): ULong {
        return when(value) {
            is RustoBindingException.Initialization -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is RustoBindingException.Preprocess -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is RustoBindingException.Inference -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is RustoBindingException.Postprocess -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is RustoBindingException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: RustoBindingException, buf: ByteBuffer) {
        when(value) {
            is RustoBindingException.Initialization -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is RustoBindingException.Preprocess -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is RustoBindingException.Inference -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is RustoBindingException.Postprocess -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is RustoBindingException.InvalidInput -> {
                buf.putInt(5)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




